<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id']))redirect('index.php');require_once dirname(__DIR__).'/private/setup_mail.php';require_once dirname(__DIR__).'/private/managed_config.php';
$error=$_SESSION['connection_error']??'';$notice=$_SESSION['connection_notice']??'';unset($_SESSION['connection_error'],$_SESSION['connection_notice']);
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{$q=$pdo->prepare('SELECT email,password_hash FROM admins WHERE id=?');$q->execute([$_SESSION['admin_id']]);$owner=$q->fetch();require_once dirname(__DIR__).'/private/platform.php';if(!$owner||!gszLoginAttempt('connections:'.$owner['email'],(string)($_SERVER['REMOTE_ADDR']??''))||!password_verify((string)($_POST['owner_password']??''),$owner['password_hash']))throw new RuntimeException('Inhaberpasswort nicht bestätigt.');gszLoginAttempt('connections:'.$owner['email'],(string)($_SERVER['REMOTE_ADDR']??''),true);$action=(string)($_POST['action']??'');
 if($action==='mail'){gszManagedSave(gszSetupMailValidate($_POST,$config));$_SESSION['connection_notice']='Postfach sicher gespeichert. Zum Versand ist eine zusätzliche bewusste Freigabe erforderlich.';}
 elseif($action==='probe')$_SESSION['connection_probe']=gszSetupMailProbe($config);
 elseif($action==='send_release'){if(empty($_POST['confirm_send_release'])||empty($_POST['confirm_mail_tested'])||empty($config['mail_sent_folder']))throw new RuntimeException('Postfachprüfung, überprüften Gesendet-Ordner und ausdrückliche Versandfreigabe bestätigen.');gszManagedSave(['allow_mail_send'=>true]);$_SESSION['connection_notice']='Versand freigegeben. Jede Nachricht benötigt weiterhin ihre eigene Versandbestätigung. Hier wurde keine Nachricht versendet.';}
 else throw new RuntimeException('Aktion unbekannt.');
 }catch(Throwable $e){$_SESSION['connection_error']=$e instanceof PDOException?'Datenbankaktion fehlgeschlagen.':(str_starts_with($e->getMessage(),'GSZ_')?'Private Konfiguration oder Dienste prüfen; keine Geheimnisse ausgegeben.':$e->getMessage());}redirect('connections.php');}
function cf(string $action):void {echo '<input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="action" value="'.e($action).'">';}
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dienste sicher einrichten</title><link rel="stylesheet" href="assets.css"></head><body><main><h1>Dienste sicher einrichten</h1><?php if($error):?><p class="error" role="alert"><?=e($error)?></p><?php endif;if($notice):?><p role="status"><?=e($notice)?></p><?php endif?>
<section class="card"><h2>STRATO-Postfach</h2><form method="post"><?php cf('mail');?><label>Postfachadresse<input type="email" name="mail_user" value="<?=e($config['mail_user']?:'info@gebaeudeservice-zentrum.de')?>" required></label><label>Postfachpasswort (leer = beibehalten)<input type="password" name="mail_pass" autocomplete="new-password"></label><label>Signatur<textarea name="mail_signature" maxlength="5000"><?=e($config['mail_signature'])?></textarea></label><?php foreach(['mail_sent_folder'=>'Gesendet-Ordner','mail_trash_folder'=>'Papierkorb-Ordner','mail_archive_folder'=>'Archiv-Ordner'] as $key=>$label):?><label><?=e($label)?><input name="<?=e($key)?>" value="<?=e($config[$key])?>"></label><?php endforeach?><label><input type="checkbox" name="mail_enabled" value="1" <?=!empty($config['mail_enabled'])?'checked':''?>> Postfach aktivieren</label><label>Inhaberpasswort bestätigen<input type="password" name="owner_password" autocomplete="current-password" required></label><button>Postfach speichern</button></form>
<form method="post"><?php cf('probe');?><label>Inhaberpasswort<input type="password" name="owner_password" required></label><button>IMAP/SMTP prüfen, ohne Mailversand</button></form><?php if(isset($_SESSION['connection_probe'])):?><pre style="white-space:pre-wrap;overflow-wrap:anywhere"><?=e(json_encode($_SESSION['connection_probe'],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT))?></pre><?php endif?>
<form method="post"><?php cf('send_release');?><label>Inhaberpasswort<input type="password" name="owner_password" required></label><label><input type="checkbox" name="confirm_mail_tested" value="1" required> Postfach und Gesendet-Ordner tatsächlich geprüft</label><label><input type="checkbox" name="confirm_send_release" value="1" required> SMTP-Versand ausdrücklich freigeben; einzelne Nachrichten weiterhin bestätigen</label><button>Versandfunktion freigeben (sendet keine Mail)</button></form></section>
